SELECT "id", "name", "email", "password", "phone", "role", "latitude", "longitude", "isEmailVerified", "emailVerificationToken", "passwordResetToken", "passwordResetExpires", "passwordResetAttempts", "authVersion", "emailVerificationExpires", "googleId", "appleId", "cardUserKey", "createdAt", "updatedAt", "deletedAt" FROM "Users" AS "User" WHERE ("User"."deletedAt" IS NULL AND "User"."id" = '3f4a34fd-44cd-4ec3-8a21-a715239e071b');

SELECT "Business"."id", "Business"."name", "Business"."description", "Business"."address", "Business"."city", "Business"."district", "Business"."latitude", "Business"."longitude", "Business"."phone", "Business"."imageUrl", "Business"."rating", "Business"."isActive", "Business"."isApproved", "Business"."approvalStatus", "Business"."categoryId", "Business"."createdAt", "Business"."updatedAt", (
  6371 * acos(
    LEAST(1, GREATEST(-1,
      cos(radians(41)) * cos(radians("Business"."latitude"))
        * cos(radians("Business"."longitude") - radians(29))
      + sin(radians(41)) * sin(radians("Business"."latitude"))
    ))
  )
) AS "distance", "category"."id" AS "category.id", "category"."name" AS "category.name", "category"."slug" AS "category.slug" FROM "Businesses" AS "Business" LEFT OUTER JOIN "Categories" AS "category" ON "Business"."categoryId" = "category"."id" WHERE ("Business"."deletedAt" IS NULL AND (("Business"."isActive" = true AND "Business"."isApproved" = true AND "Business"."latitude" BETWEEN '40.55084441250449' AND '41.44915558749551' AND "Business"."longitude" BETWEEN '28.404863010533234' AND '29.595136989466766') AND (
  6371 * acos(
    LEAST(1, GREATEST(-1,
      cos(radians(41)) * cos(radians("Business"."latitude"))
        * cos(radians("Business"."longitude") - radians(29))
      + sin(radians(41)) * sin(radians("Business"."latitude"))
    ))
  )
) <= 50)) ORDER BY (
  6371 * acos(
    LEAST(1, GREATEST(-1,
      cos(radians(41)) * cos(radians("Business"."latitude"))
        * cos(radians("Business"."longitude") - radians(29))
      + sin(radians(41)) * sin(radians("Business"."latitude"))
    ))
  )
) ASC LIMIT 500;

